public int luckBalance(int k, int[][] contests) {
    List<Integer> important = new ArrayList<>();
    int base = 0;
    for (int[] c : contests) {
        if (c[1] == 0) base += c[0];
        else important.add(c[0]);
    }
    int m = important.size();
    int best = Integer.MIN_VALUE;
    for (int mask = 0; mask < (1 << m); mask++) {
        if (Integer.bitCount(mask) > k) continue;
        int luck = base;
        for (int i = 0; i < m; i++) {
            luck += ((mask & (1 << i)) != 0) ? important.get(i) : -important.get(i);
        }
        best = Math.max(best, luck);
    }
    return best;
}

