def luck_balance(k: int, contests: list[list[int]]) -> int:
    important: list[int] = []
    base = 0
    for luck, is_important in contests:
        if is_important == 0:
            base += luck
        else:
            important.append(luck)
    m = len(important)
    best = float("-inf")
    for mask in range(1 << m):
        if bin(mask).count("1") > k:
            continue
        total = base
        for i in range(m):
            total += important[i] if mask & (1 << i) else -important[i]
        best = max(best, total)
    return int(best)

