public int luckBalance(int k, int[][] contests) {
    List<Integer> important = new ArrayList<>();
    int luck = 0;
    for (int[] c : contests) {
        if (c[1] == 0) {
            luck += c[0];
        } else {
            important.add(c[0]);
        }
    }
    important.sort(Comparator.reverseOrder());
    for (int i = 0; i < important.size(); i++) {
        luck += (i < k) ? important.get(i) : -important.get(i);
    }
    return luck;
}

