def luck_balance(k: int, contests: list[list[int]]) -> int:
    important: list[int] = []
    luck = 0
    for amount, is_important in contests:
        if is_important == 0:
            luck += amount
        else:
            important.append(amount)
    important.sort(reverse=True)
    for i, amount in enumerate(important):
        luck += amount if i < k else -amount
    return luck

